using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain the static queue to avoid cross-test pollution
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesNotification()
        {
            // Act
            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
        {
            // Act
            _sut.SendNotification("Course", "42", EntityOperation.UPDATE, "Teacher");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            // Act
            _sut.SendNotification("Department", "5", EntityOperation.DELETE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
        {
            // Act
            _sut.SendNotification("Student", "1", "Test Student", operation, "User");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains(expectedVerb, notification.Message);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            // Act
            var result = _sut.ReceiveNotification();

            // Assert
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleMessages_ReturnsFIFO()
        {
            // Arrange
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
            _sut.SendNotification("C", "3", EntityOperation.DELETE);

            // Act & Assert
            var first = _sut.ReceiveNotification();
            Assert.Equal("A", first.EntityType);

            var second = _sut.ReceiveNotification();
            Assert.Equal("B", second.EntityType);

            var third = _sut.ReceiveNotification();
            Assert.Equal("C", third.EntityType);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToCurrentTime()
        {
            // Arrange
            var before = DateTime.Now.AddSeconds(-1);

            // Act
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.True(notification.CreatedAt >= before);
            Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1));
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // Act & Assert (no-op implementation, just verify no exception)
            var exception = Record.Exception(() => _sut.MarkAsRead(1));
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_CreateOperation_WithDisplayName_FormatsCorrectly()
        {
            // Act
            _sut.SendNotification("Instructor", "5", "Dr. Smith", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.Equal("New Instructor 'Dr. Smith' has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_UpdateOperation_WithDisplayName_FormatsCorrectly()
        {
            // Act
            _sut.SendNotification("Course", "101", "Chemistry", EntityOperation.UPDATE, "User");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.Equal("Course 'Chemistry' has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_WithDisplayName_FormatsCorrectly()
        {
            // Act
            _sut.SendNotification("Department", "3", "Math", EntityOperation.DELETE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.Equal("Department 'Math' has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_FormatsWithId()
        {
            // Act
            _sut.SendNotification("Student", "99", EntityOperation.CREATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.Equal("New Student (ID: 99) has been created", notification.Message);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            // Act & Assert
            var service = new NotificationService();
            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_FirstPage_ReturnsCorrectItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Equal(10, result.Count);
            Assert.Equal(1, result[0]);
            Assert.Equal(10, result[9]);
        }

        [Fact]
        public void Create_SecondPage_ReturnsCorrectItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 2, 10);

            // Assert
            Assert.Equal(10, result.Count);
            Assert.Equal(11, result[0]);
            Assert.Equal(20, result[9]);
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 3, 10);

            // Assert
            Assert.Equal(5, result.Count);
            Assert.Equal(21, result[0]);
            Assert.Equal(25, result[4]);
        }

        [Fact]
        public void Create_SetsPageIndexCorrectly()
        {
            // Arrange
            var source = Enumerable.Range(1, 50).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 3, 10);

            // Assert
            Assert.Equal(3, result.PageIndex);
        }

        [Fact]
        public void Create_CalculatesTotalPagesCorrectly()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Equal(3, result.TotalPages);
        }

        [Theory]
        [InlineData(10, 10, 1)]
        [InlineData(11, 10, 2)]
        [InlineData(20, 10, 2)]
        [InlineData(21, 10, 3)]
        [InlineData(1, 10, 1)]
        [InlineData(0, 10, 0)]
        public void Create_TotalPages_CalculatedCorrectly(int itemCount, int pageSize, int expectedTotalPages)
        {
            // Arrange
            var source = Enumerable.Range(1, itemCount > 0 ? itemCount : 1).Take(itemCount).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, pageSize);

            // Assert
            Assert.Equal(expectedTotalPages, result.TotalPages);
        }

        [Fact]
        public void HasPreviousPage_OnFirstPage_ReturnsFalse()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_OnSecondPage_ReturnsTrue()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 2, 10);

            // Assert
            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_OnFirstPage_ReturnsTrue()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_OnLastPage_ReturnsFalse()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 3, 10);

            // Assert
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Constructor_SetsPropertiesCorrectly()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var result = new PaginatedList<string>(items, 10, 2, 5);

            // Assert
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(2, result.TotalPages);
            Assert.Equal(3, result.Count);
            Assert.Equal("a", result[0]);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            // Arrange
            var source = Enumerable.Empty<int>().AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }
    }
}

