                FirstMidName = "John"
            };

            // Act
            var fullName = student.FullName;

            // Assert
            Assert.Equal("Smith, John", fullName);
        }

        [Theory]
        [InlineData("Doe", "Jane", "Doe, Jane")]
        [InlineData("O'Connor", "Pat", "O'Connor, Pat")]
        [InlineData("Kim", "Sun-Mi", "Kim, Sun-Mi")]
        public void FullName_VariousNames_FormatsCorrectly(string lastName, string firstName, string expected)
        {
            // Arrange
            var instructor = new Instructor
            {
                LastName = lastName,
                FirstMidName = firstName
            };

            // Act & Assert
            Assert.Equal(expected, instructor.FullName);
        }
    }

    public class EnrollmentTests
    {
        [Fact]
        public void Enrollment_GradeCanBeNull()
        {
            // Arrange
            var enrollment = new Enrollment { EnrollmentID = 1, CourseID = 1, StudentID = 1 };

            // Assert
            Assert.Null(enrollment.Grade);
        }

        [Theory]
        [InlineData(Grade.A)]
        [InlineData(Grade.B)]
        [InlineData(Grade.C)]
        [InlineData(Grade.D)]
        [InlineData(Grade.F)]
        public void Enrollment_AllGradeValues_Valid(Grade grade)
        {
            // Arrange & Act
            var enrollment = new Enrollment { Grade = grade };

            // Assert
            Assert.Equal(grade, enrollment.Grade);
        }
    }

    public class CourseModelTests
    {
        [Fact]
        public void Course_PropertiesSetCorrectly()
        {
            // Arrange & Act
            var course = new Course
            {
                CourseID = 1001,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/images/chem.png"
            };

            // Assert
            Assert.Equal(1001, course.CourseID);
            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Equal("/images/chem.png", course.TeachingMaterialImagePath);
        }
    }

    public class DepartmentModelTests
    {
        [Fact]
        public void Department_PropertiesSetCorrectly()
        {
            // Arrange & Act
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Computer Science",
                Budget = 200000m,
                StartDate = new System.DateTime(2000, 1, 1),
                InstructorID = 5
            };

            // Assert
            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("Computer Science", dept.Name);
            Assert.Equal(200000m, dept.Budget);
            Assert.Equal(5, dept.InstructorID);
        }

        [Fact]
        public void Department_InstructorID_CanBeNull()
        {
            // Arrange & Act
            var dept = new Department { Name = "Test", InstructorID = null };

            // Assert
            Assert.Null(dept.InstructorID);
        }
    }

    public class NotificationModelTests
    {
        [Fact]
        public void Notification_PropertiesSetCorrectly()
        {
            // Arrange & Act
            var notification = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "42",
                Operation = "CREATE",
                Message = "Test message",
                CreatedAt = new System.DateTime(2023, 6, 15, 10, 30, 0),
                CreatedBy = "Admin",
                IsRead = false,
                ReadAt = null
            };

            // Assert
            Assert.Equal(1, notification.Id);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Test message", notification.Message);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Null(notification.ReadAt);
        }

        [Fact]
        public void Notification_ReadAt_CanBeSet()
        {
            // Arrange & Act
            var readTime = new System.DateTime(2023, 6, 16);
            var notification = new Notification
            {
                IsRead = true,
                ReadAt = readTime
            };

            // Assert
            Assert.True(notification.IsRead);
            Assert.Equal(readTime, notification.ReadAt);
        }
    }

    public class EntityOperationTests
    {
        [Fact]
        public void EntityOperation_HasExpectedValues()
        {
            // Assert
            Assert.Equal(0, (int)EntityOperation.CREATE);
            Assert.Equal(1, (int)EntityOperation.UPDATE);
            Assert.Equal(2, (int)EntityOperation.DELETE);
        }

        [Fact]
        public void EntityOperation_ToStringReturnsName()
        {
            // Assert
            Assert.Equal("CREATE", EntityOperation.CREATE.ToString());
            Assert.Equal("UPDATE", EntityOperation.UPDATE.ToString());
            Assert.Equal("DELETE", EntityOperation.DELETE.ToString());
        }
    }
}

